// typert.mjs — the drafts package's Typert artifact generator.
//
// THE LAW (AGENTS.md LAW 1 — the copy-don't-invent law): client-side
// Remote faces are MOUNTED from artifacts the DSH typert generator
// emits ("Generated by @deepseek-ai/dsh-typert-generator from the
// Host FaceModel — do not edit"). Hand-rolling descriptors is the
// degenerate path; this script is the sanctioned copy:
// WorkspaceTypertGenerator over the repo's host aggregate
// (tsconfig.host.json), one focused pass for this package, artifacts
// committed under lib/ exactly as DSH packages commit theirs. The
// write law mirrors the generator's own tsdown plugin
// (typert.generator/src/tsdown-plugin.ts emitArtifacts):
//   lib/typert.host.js / .d.ts           — the host-face contribution
//   lib/typert.remote-client.js / .d.ts   — the browser contribution
//
// Run:   node scripts/typert.mjs        (after `pnpm run build`)
import { mkdirSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { WorkspaceTypertGenerator } from '@deepseek-ai/dsh-typert-generator'

const pkgRoot = resolve(import.meta.dirname, '..')
const repoRoot = resolve(pkgRoot, '../../..')

const generator = new WorkspaceTypertGenerator(repoRoot, {
  hostConfig: 'tsconfig.host.json',
  checkDiagnostics: true,
})
const results = generator.generate(['@melite/estate-drafts'])
if (results.length === 0) throw new Error('typert: @melite/estate-drafts contributed no face — check tsconfig.host.json includes its sources')
for (const artifact of results) {
  // packageRoot may ride RELATIVE to the repo root (the generator's
  // registration face) — resolve against repoRoot, never the CWD
  // (pnpm runs scripts with CWD = the package dir; a bare join
  // nested a stray packages/<...>/lib tree INSIDE the package).
  const pkgRootAbs = artifact.packageRoot.startsWith('/')
    ? artifact.packageRoot : resolve(repoRoot, artifact.packageRoot)
  const output = join(pkgRootAbs, 'lib')
  mkdirSync(output, { recursive: true })
  writeFileSync(join(output, `typert.${artifact.face}.js`), artifact.js)
  writeFileSync(join(output, `typert.${artifact.face}.d.ts`), artifact.dts)
  console.log('typert:', artifact.package, 'face:', artifact.face,
    '| exports:', artifact.exports.join(', ') || '(none)')
  if (artifact.remote === undefined) {
    console.log('  remote: NONE — no Remote methods found; the browser contribution was not emitted')
    continue
  }
  writeFileSync(join(output, 'typert.remote-client.js'), artifact.remote.js)
  writeFileSync(join(output, 'typert.remote-client.d.ts'), artifact.remote.dts)
  // SRC-PLANE TWIN (the two-plane law): the merge declarations that
  // give TypertRemoteMap its rows must exist on the SOURCE plane too
  // — a typecheck face (paths → src) pulling this package's ./remote
  // door resolves the same merges the built lib carries.
  writeFileSync(join(pkgRootAbs, 'src/typert.remote-client.d.ts'), artifact.remote.dts)
  console.log('  remote: lib/typert.remote-client.js', '(' + artifact.remote.js.length + ' chars)')
}
